 web.on("/status",HTTP_GET,[]{String out="{\"camera\":"+jsString(camStatus)+",\"ip\":"+jsString(WiFi.status()==WL_CONNECTED?WiFi.localIP().toString():WiFi.softAPIP().toString())+",\"wifi\":"+jsString(WiFi.status()==WL_CONNECTED?"Connected":"Setup mode")+",\"count\":"+String(count)+",\"engine\":"+jsString(decodeMode)+",\"nativeValue\":"+jsString(nativeValue)+",\"nativeFormat\":"+jsString(nativeFormat)+",\"nativeError\":"+jsString(nativeError)+",\"nativeMs\":"+String(nativeMs)+",\"nativeFrames\":"+String(nativeFrames)+",\"cpuMHz\":"+String(cpuMHz)+",\"wifiPowerSave\":"+(wifiPowerSave?"true":"false")+",\"jpegQuality\":"+String(jpegQuality)+",\"idleBrightness\":"+String(idleBrightness)+",\"successBrightness\":"+String(successBrightness)+",\"confirmMs\":"+String(confirmMs)+",\"resolution\":"+jsString(scanResolution)+",\"rotation\":"+String(rotation)+",\"led\":"+(ledOn?"true":"false")+",\"capture\":"+jsString(captureState)+",\"focus\":"+jsString(focusState)+",\"scans\":[";unsigned n=min(count,50u);for(unsigned i=0;i<n;i++){if(i)out+=",";out+=jsString(history[(count-1-i)%50]);}out+="],\"boot\":"+String(bootId)+",\"records\":[";for(unsigned j=0;j<n;j++){unsigned id=count-j,i=(id-1)%50;if(j)out+=",";out+="{\"id\":"+String(id)+",\"format\":"+jsString(recordFormat[i])+",\"raw\":"+jsString(recordRaw[i])+",\"uptime\":"+String(recordUptime[i])+"}";}out+="]}";web.send(200,"application/json",out);});
